INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yarne', 145416, '2021-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zzr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar59hu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yarne', 'Yarne is a relaxing puzzle game that can be played at any pace. For new players, beginning puzzles will be simple and will teach you techniques that will be helpful as you continue to play. With over 100 levels, you will encounter new challenges that will constantly reframe how you view the game. There is no wrong way to play Yarne! As you play you will unlock unique color palettes and new shapes, allowing for even more individuality as you can choose the aesthetics you wish to play with. Play at your own speed or strive to optimize your space to get as many points as possible. You can move any shape at any time, so you''ll never be locked into anything and can rethink your strategy at any time.' FROM games WHERE igdb_id = 145416 ON CONFLICT (game_id, language_code) DO NOTHING;
