INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Rivals: The Court', 'Ultimate Rivals: The Court is an action-packed basketball arcade sports game bringing 140+ superstars together in a digital world in the near future. Powerhouse squads consisting of athletes from the NHL, NBA, MLB, WNBA, NFL Players Association, and US women’s soccer national team go head-to-head in 3-on-3 games with tons of above-the-rim acrobatics. The game includes top athletes ranging from all-time greats like Wayne Gretzky to sports biggest stars like Alex Morgan. In addition, WWE Superstars will join the roster in future updates including Roman Reigns, Charlotte Flair, and Dwayne Johnson (The Rock).' FROM games WHERE igdb_id = 150098 ON CONFLICT (game_id, language_code) DO NOTHING;
