INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('20-ladies', 178798, '2021-11-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co48x9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar19xk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '20 Ladies', 'Enter a world of simple pleasures and minimalistic design, where your only goal is to navigate cleverly arranged stages, avoid spikes and locate beautiful female companions hidden in the environment. But beware of hazards! Break a heart three times, and you’ll instantly respawn at the beginning, with your lady counter reset to zero. You’ll need to touch them all without dying in order to proceed to the next stage and unlock an alluring image for each one you complete. Platforms in the foreground are silhouetted against lush hand-drawn backdrops. Clouds pass by overhead, trees sway in the breeze and historical architecture dots the landscape as mellow tunes accompany you on a chill quest for love. Your best times are tracked with each playthrough, inviting you to come back and top your own record.' FROM games WHERE igdb_id = 178798 ON CONFLICT (game_id, language_code) DO NOTHING;
