INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SCP: Containment Breach Multiplayer', 'Multiplayer survival horror game based on stories from the SCP Foundation. The game is about a facility containing anomalous entities known as SCPs. When a catastrophic containment breach occurs at one of the facilities, it is your main goal to escape the facility. Try to escape with your friends!' FROM games WHERE igdb_id = 314780 ON CONFLICT (game_id, language_code) DO NOTHING;
