INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Adventure', 'Dungeon Adventure is a game where you are exploring massive dungeons with the hope of getting out alive, while also eliminating all the enemies. There are lots of things you can find in there, from powerful enemies to some of the best gadgets and coolest items. But be aware, you might not be able to come out from that place. Grab Dungeon Adventure right now and engage yourself in the most exciting and rewarding game experience!' FROM games WHERE igdb_id = 180983 ON CONFLICT (game_id, language_code) DO NOTHING;
