INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Builder', 'Road Builder is a logic puzzle game based on the system of creating roads and managing traffic flow. The player''s task is to connect selected entry and exit roads by creating complex structures of intersections and junctions so that traffic collides with each other as little as possible.' FROM games WHERE igdb_id = 172994 ON CONFLICT (game_id, language_code) DO NOTHING;
