INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Philosopher''s Stone and Minerva', 'It is a world where the human world and the demon world coexist. The demon king, "Orkus", defeats the former king and takes the current king away. The warrior Minerva goes to the Demon King''s castle to bring back the king. Will Minerva and Merus be able to protect the world?' FROM games WHERE igdb_id = 192512 ON CONFLICT (game_id, language_code) DO NOTHING;
