INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vacation Adventures: Cruise Director 5', 'Arrange fabulous excursions in the Caribbean, Europe and South America. Visit amazing tourist sights and landmarks in cities such as London, Edinburgh, Barcelona, Vienna and Istanbul. Go inside the world famous Windsor Castle where British Royal Weddings take place. Help passengers with cabins, shopping, dining, leisure on board and at Ports of Call along the way. Collect souvenirs of the cruise. Look for hundreds of hidden objects, items lost by passengers, trash for recycling. Play superb mini-games and earn badges for your achievements.' FROM games WHERE igdb_id = 180009 ON CONFLICT (game_id, language_code) DO NOTHING;
