INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('barbero', 186556, '2021-10-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5721.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1c43.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbero', 'Become a groomer and make dogs look lovely again. Choose your favorite trimmer and start getting acquainted with a whole bunch of different dogs. All these animals have common features: they like to mischief and are not afraid to get dirty - so prepare for a good wash! Be watchful and catch the objects before they drop down to unlock special features. Make your trimmer bigger, highlight the remaining dirt or gain more time. You can either play by yourself or invite up to four friends to join you locally. The third time is the charm! In a singleplayer mode you’ll need to complete all of the chapters. To win a multiplayer game you just need to be the fastest and most efficient groomer three times in a row. Show your friends who''s the best barber in town! Catch the paint and cover your opponents’ part of the screen to slow them down. Have you ever dreamt about being a dog groomer? Perhaps you simply love dogs and want to care for them? Then this game is perfect for you. Don’t let the dogs wait!' FROM games WHERE igdb_id = 186556 ON CONFLICT (game_id, language_code) DO NOTHING;
