INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beat Workers', 'Beat Workers is set in a futuristic world where most of the work is done by robots. You''re put in the shoes of the Great Architect, one of the last employed human being. Your job ? Rebuilding monuments from the Great Country’s past to offer some more distraction to the mostly idle Great People.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 175133 AND ge.slug = 'music' ON CONFLICT DO NOTHING;
