INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Joojee''s Journey', 'In this whimsical narrative adventure, you’ll play as Joojee, a lovable bunny who suddenly wakes up without her memory. Armed with nothing but her charm and a mysterious magic brush that allows her to enter anyone’s mind, Joojee goes on a journey to recover her lost memories while helping others overcome their own troubles.' FROM games WHERE igdb_id = 180974 ON CONFLICT (game_id, language_code) DO NOTHING;
