INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crypto Royale', 'Crypto Royale is a browser-based, free-to-play, play-to-earn crypto game in which players compete for fame, glory and a little profit. Last man standing wins crypto. No up-front investment. No downloads. No signups. Get into a game in 30 seconds and win! The game is purposefully designed to be simple to play yet difficult to master. Every day 1000+ players congregate on the battlefield as they fight to see who can survive and claim the game’s HRC-20 token – ROY.' FROM games WHERE igdb_id = 225730 ON CONFLICT (game_id, language_code) DO NOTHING;
