INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('choro-2021', 186127, '2021-12-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4bay.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choro 2021', 'Choro 2021 is a mobile game released for Android and iOS on 5 December 2021. The game follows a cowboy in a dystopian Venezuela that has to fight malandros, soldiers, zombies and witches, while finding references of the country, such as an empanada, a Toronto or a Riko Malt. In the first released level, the protagonist has to cross Mission Zamora and fight the witch Bruja Maruja. Developed by Venezuelan filmmaker Carl Zitelmann and based in an homonymous novel, Choro 2021 is an action and adventure metroidvania, with a design similar to Contra, Mega Man, Castlevania and Ninja Gaiden.' FROM games WHERE igdb_id = 186127 ON CONFLICT (game_id, language_code) DO NOTHING;
