INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('devolver-tumble-time', 152205, '2021-11-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3994.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scks5t.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devolver Tumble Time', 'Devolver Tumble Time is the future of physics-based puzzle gameplay, elegant monetization, and strategic brand integration. Choose characters from a packed roster of your favorite Devolver Digital games and rack up big points matching and clearing their impossibly adorable heads from the tumbler. Get hyped enough and unleash each character''s special ability to clear huge chunks and earn power-ups to create chaotic chain reactions. Then maybe watch some entertaining ads. Earn and unlock new characters, compete in daily challenges, and buy stuff. Buying stuff is so great. Don''t forget to keep an eye out for new character drops from your favorite Devolver Digital games and maybe even from ones you''ve never heard of in your life. Plus delicious ads. Watch ''em up real good. Physics-Based Fun! Matching-Based Fun! Baffling Amounts of Virtual Currency! Collectible Donuts, Flowers, & Socks! Microtransaction-Based Fun! Enjoyable Advertisements!' FROM games WHERE igdb_id = 152205 ON CONFLICT (game_id, language_code) DO NOTHING;
