INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '4 Witch Seasons & Convenant', '刚刚从孤儿院离开的少年遇到了自己亲生父亲的女儿，被要求前往她所在的城市的大学。少年进入了探索都市传说的社团，当在快乐的探索世界的大学生活之中度过的时候，城市之中释放出的吞噬一切的怪物出现在了他的面前，如同神明一样的神秘少女拯救。' FROM games WHERE igdb_id = 173235 ON CONFLICT (game_id, language_code) DO NOTHING;
