INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monopoly-solitaire', 183134, '2021-11-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4xgz.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monopoly Solitaire', 'Classic Solitaire meets Monopoly in this new mash-up brought to you by Hasbro and the original creators of Solitaire! Now is your chance to play these two classic games for FREE and become a Monopoly millionaire. Easy to play but impossible to put down, MONOPOLY Solitaire is a relaxing card game with an exciting twist. Earn Monopoly Bucks and roll the dice as you play each solitaire hand. Work your way along the Boardwalk, collecting properties and building houses and hotels as you go. You’ll use your hard-earned cash from playing solitaire! Puzzle your way through each solitaire challenge to earn more rolls and get ahead of your opponents. Collect rent from all your properties and ace the game by being the richest landlord on the Boardwalk!' FROM games WHERE igdb_id = 183134 ON CONFLICT (game_id, language_code) DO NOTHING;
