INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oozing Islands', 'Enjoy freedom of movement in full 3D with no fixed paths in this tower defense and RTS hybrid. Your units are your towers and you can build fences anywhere. Set your units'' behavior to create a perfect team of defenders. Two leader boards let you play forever!' FROM games WHERE igdb_id = 165685 ON CONFLICT (game_id, language_code) DO NOTHING;
