INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danganronpa: Resort Killing', 'A new killing game begins as you and 15 other participants enter... A resort? You play as Yu Narukami from the persona series. Things seem off right from the start but things only continue to get stranger in this crossover fan game based off of the Danganronpa series by Spike Chunsoft. Featuring characters from Persona, Re:Zero, Yugioh, Super Mario, Touhou, Konosuba, River City, YiiK, Katawa Shoujo, Danganronpa, as well as Gordon Ramsey. Try to survive and uncover the truth inside this deadly resort.' FROM games WHERE igdb_id = 228264 ON CONFLICT (game_id, language_code) DO NOTHING;
