INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sunrise on the Moon', 'On the moon, consecutive sunrises and sunsets occur approximately 29 1/2 days apart. For as long as Maria has lived in the Lunar Colonies, she''s never failed in her tradition to watch the sunrises from the station''s viewing platform. As she''s waiting for her tram to arrive, however, she encounters a curious young woman that piques her interest. For once, Maria feels compelled to engage in a friendly conversation.' FROM games WHERE igdb_id = 181282 ON CONFLICT (game_id, language_code) DO NOTHING;
