INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beach Volleyball Challenge', 'Feel the heat of sunshine, suit up in a light outfit, and start the emotional battle in Beach Volleyball Challenge. It’s the best simulator of beach volleyball available on the market! Get a virtual trip to places like Copacabana or Manhattan Beach – the capitals of that summer sport! This sport game will serve you emotions comparable to that given on tournaments like Manhattan Beach Open, New York Open, or Huntington Beach Open!' FROM games WHERE igdb_id = 172845 ON CONFLICT (game_id, language_code) DO NOTHING;
