INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('football-run', 186957, '2021-10-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57ny.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1cav.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Football Run', 'Football– the sport featuring kicking a ball across a pitch has various names in different corners of the world. However, it''s not the name that matters most – all that really matters is what stars are doing with the ball. What would you say if somebody made a platform game with that? Football Run – the latest platform game by Simplicity Games – will let you feel the atmosphere that millions of fans worldwide on every football game! Our platform game features dynamic levels set in the world of football! Right from the get-go, our platform game clearly shows that there should be only two things in the world – and your opponents in the game are people fascinated by the sport. Even the best players in the world would find it difficult to keep up with the pace of the game. The game is very quick and your goal is to sprint to the very end, gather all the coins and items on the way – all of them are inspired by football! Our platform game allows you to play as your favorite footballers running through the levels – we don’t know who you’re the biggest fan, but you should be able to choose one from our wide selection of players. If you loved the game with Head and Soccer in the title – the one, where the players had big heads – we can assure you that our game is better, filled with fun and great gameplay that you can experience with each subsequent…' FROM games WHERE igdb_id = 186957 ON CONFLICT (game_id, language_code) DO NOTHING;
