INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('horseshoe-crab-rescue', 180970, '2021-11-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ced.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scenz0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Horseshoe Crab Rescue!', 'It''s breeding time for the horseshoe crabs, which means they will come to the beach to lay and fertilize eggs. Horseshoe crabs have been around for hundreds of millions of years, but they have one weakness - if they get flipped on their back on the beach, they get stuck! Luckily, humans can help them out. In Horseshoe Crab Rescue!, you will help out these amazing creatures by flipping horseshoe crabs that have gotten stranded on their backs. Hurry around the beach and try to rescue as many horseshoe crabs as you can before time runs out! Horseshoe Crab Rescue! is a casual game with light educational elements. Play through 15 stages of increasing difficulty while trying to beat your top scores, and learn a few facts along the way.' FROM games WHERE igdb_id = 180970 ON CONFLICT (game_id, language_code) DO NOTHING;
