INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hexahedral Pathfinder', 'Taking a twist on the classic box pushers, this simple yet deceivingly challenging puzzler will push the limits of your imagination, as you control the blocks in unison through Contains over 150 patiently handcrafted levels and 50 additional challenge levels for those confident in their skills. Features the full use of 3D space, portals, colour changers, explosions, doors and sensors, and much more!' FROM games WHERE igdb_id = 108418 ON CONFLICT (game_id, language_code) DO NOTHING;
