INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turgor Pressure', 'After a dive team sent to explore an abandoned facility goes missing, you are tasked with piloting a ROV down below the surface of the ocean to see if you can track them down and either guide them back up, or at least confirm that they''re dead. Your ROV is equipped with a scanning system to help you determine what may have happened to the team. Good luck out there, and remember: Something''s wrong with the ocean.' FROM games WHERE igdb_id = 177318 ON CONFLICT (game_id, language_code) DO NOTHING;
