INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tap-away', 230515, '2021-05-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6q7q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2fqi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tap Away', 'Tap the blocks to make them fly away and clear the screen. But the blocks will only fly in one direction, so you’ve got to approach this brain teaser carefully! Slide your finger around the screen to rotate the shape and attack the blocks from every angle! As you progress, the blocks form bigger and bigger shapes, and the blocks themselves change form, so you’ll need to get your thinking hat on to solve the puzzles in this 3D puzzle game. And that’s not it! There are skins and themes you can unlock as you get further, as well as challenges to keep you on your toes. In this fun and colourful game, you challenge your logic, critical thinking, and precision. Do you have what it takes?' FROM games WHERE igdb_id = 230515 ON CONFLICT (game_id, language_code) DO NOTHING;
