INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Staxter', 'This game is a spiritual successor to Kirby Star Stacker. Enjoy levels of great size, or intense restriction. Chill with an endless mode, or try to speed run it! A relaxing game about the garden, enjoy the sounds of the woods, while using your bug friends to collect the flowers. Sandwich flowers or buds between two matching bug friends to collect them! Or, sandwich special blocks, like the watering well or the lawn mower to use special effects.' FROM games WHERE igdb_id = 186167 ON CONFLICT (game_id, language_code) DO NOTHING;
