INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tents and Trees', 'A deceptively simple puzzle game written for the Fairchild Channel F. The aim of the game is to place a tent adjacent to each tree in such a way that the correct number are in each row and column, as shown by the numbers alongside. When you have the correct number in a particular row or column, the number will turn green. Tents cannot be placed if there is no tree to the left, right, above or below.' FROM games WHERE igdb_id = 123399 ON CONFLICT (game_id, language_code) DO NOTHING;
