INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dark-water-slime-invader', 147076, '2021-03-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57du.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ararj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Water: Slime Invader', 'Dark Water is a story about a granddaughter and grandmother''s adventure to save their village from cursed slime attacks. Use various bow skills to defeat slimes, overcome the traps and save the village from the crisis. Dark Water, a Fantasy side-scrolling action game, has won the following awards: ・Unity 2020 Best Indie Game #1 ・Won second place in the Game Audition ・Nominated for Global Indie Game Developer Contest Fantastic graphics in pastel watercolor style! ・Clear the stage using various abilities of granddaughter and grandmother, such as shooting a bow and riding a parachute. ・Collaborate with grandmother on heavy rocks and traps that cannot be solved by granddaughter alone. ・Consider the terrain of each stage and use the appropriate abilities to clear the stage. ・Enjoy a long adventure by defeating diverse monsters in various fantastic stages. ・Enjoy the game by listening great game Music composed by Manami Matsumae, a famous musical composer of the Mega Man series. Granddaughter and grandmother lived happily in a peaceful village. One day, slime monsters attacked the village and village inhabitants. Use diverse skills of granddaughter and grandmother to defeat slime invasion and slain the slime boss. Regain a peaceful village from the slime invaders!' FROM games WHERE igdb_id = 147076 ON CONFLICT (game_id, language_code) DO NOTHING;
