INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight on the Milky Way', 'In the depths of space, without a memory or face, you find yourself aboard a train of mystery and stars. The passengers abroad—some dangerous, some odd—offer you no answers as you search throughout the cars. The clock is slowly ticking. Your stop is coming into sight. Will you find what you are looking for on this lonely, starry night?' FROM games WHERE igdb_id = 161175 ON CONFLICT (game_id, language_code) DO NOTHING;
