INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyde & Seek', 'ALL IS FAIR IN HYDE & SEEK. BETRAY, OUTWIT, AND DEVOUR YOUR FELLOW GUESTS TO SECURE YOUR FREEDOM! You have one goal: collect gems from around the manor. But be careful - rumor has it that when night falls, the manor''s guests will turn into monsters!' FROM games WHERE igdb_id = 153060 ON CONFLICT (game_id, language_code) DO NOTHING;
