INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Escaper', 'Dream Escaper is a non-traditional Yume Nikki fangame centered around exploration. This game has a unique feature in which players can warp to different worlds (known as "layers" in-game). It features various chasers among these layers that will send the player to a game over sequence when caught. The game also includes the ability to talk to most NPCs and save from the menu.
