INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('f-sim-space-shuttle-2', 170081, '2021-08-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ttk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scdez8.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-Sim: Space Shuttle 2', 'Each flight starts at either 10,000 feet, already aligned with the runway, or at up to 50,000 feet, before banking into the heading alignment cone. During descent, the Orbiter is an unpowered glider, so you will only have one chance to get it right. Astronauts used to call it a flying brick: because of its 200,000 lbs. gross weight and low lift over drag ratio, the approach is six times steeper and two times faster than a typical airliner approach. After your first safe touchdown, chase that perfect landing, compare your high scores online with your friends, earn medals, and unlock achievements. Experiment with different wind conditions, night approaches, and even emergency scenarios or system failures. At the end of each flight, watch a replay from different camera angles.' FROM games WHERE igdb_id = 170081 ON CONFLICT (game_id, language_code) DO NOTHING;
