INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scoot Hard DX: Daytime Drama Zero', 'From the minds behind Daytime Drama, the high-octane Scoot Hard DX: Daytime Drama Zero is the prequel to the 2018 cult classic. Very loosely based on Rainbow Factory by AuroraDawn, you play as Scootaloo, who must escape the Cloudsdale Weather Corporation and get her friends back – by kicking flank! With tons of humor, an array of equine enemies, huge levels, powerful weapons, a look and feel like something off mid-2000s Newgrounds, and full voice acting, it is a unique take on the retro shooter genre that could only come from Waffle Iron Studios!' FROM games WHERE igdb_id = 230508 ON CONFLICT (game_id, language_code) DO NOTHING;
