INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Punchy Face', 'Super Punchy Face is a roguelite beat ''em up where every single thing is a weapon. Choose from dozens of techniques to create your unique fighting style, save your uncle''s dojo from getting demolished, and smash your way to the Landlord’s mansion to give him a piece of your mind.' FROM games WHERE igdb_id = 181116 ON CONFLICT (game_id, language_code) DO NOTHING;
