INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cheese Board', 'A family-friendly game of skill for mobile devices. You move a yellow ball, a giant "ball of cheese", over a play-field full of traps and obstacles. The ball is moved by rolling and tilting your device. Follow the path to earn extra points - or take the shortcut and get your cheese home the easy way. Avoid holes, traps and obstacles. It''s a game similar to popular labyrinth marble maze games, and yet it''s different!' FROM games WHERE igdb_id = 165249 ON CONFLICT (game_id, language_code) DO NOTHING;
