INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '冰嬉图卷', '2022北京冬奥会在即，本团队基于 Unity 手绘复原《冰嬉图》卷。作品共设置五大主线交互点与若干支线交互点，涵盖文字、图片、视频、3D 展示、射击游戏、情景问答、DIY、拼图等多种交互形式，使用户了解古代冰雪运动的历史知识，唤起用户对冰雪运动的热爱。' FROM games WHERE igdb_id = 162434 ON CONFLICT (game_id, language_code) DO NOTHING;
